        out.push_str(&escape_json_str(a));
        if i + 1 < cmd.aliases.len() {
            out.push(',');
        }
        out.push('\n');
    }
    indent(out, level + 1);
    out.push_str("],\n");

    indent(out, level + 1);
    out.push_str("\"flag_options\": [\n");
    for (i, fo) in cmd.flag_options.iter().enumerate() {
        format_flag_option(out, fo, level + 2);
        if i + 1 < cmd.flag_options.len() {
            out.push(',');
        }
        out.push('\n');
    }
    indent(out, level + 1);
    out.push_str("],\n");

    indent(out, level + 1);
    out.push_str("\"positionals\": [\n");
    for (i, pos) in cmd.positionals.iter().enumerate() {
        format_positional(out, pos, level + 2);
        if i + 1 < cmd.positionals.len() {
            out.push(',');
        }
        out.push('\n');
    }
    indent(out, level + 1);
    out.push_str("],\n");

    indent(out, level + 1);
    out.push_str("\"envs\": [\n");
    for (i, env) in cmd.envs.iter().enumerate() {
        format_env(out, env, level + 2);
        if i + 1 < cmd.envs.len() {
            out.push(',');
        }
        out.push('\n');
    }
    indent(out, level + 1);
    out.push_str("],\n");

    indent(out, level + 1);
    out.push_str("\"subcommands\": [\n");
    for (i, sub) in cmd.subcommands.iter().enumerate() {
        format_command(out, sub, level + 2);
        if i + 1 < cmd.subcommands.len() {
            out.push(',');
        }
        out.push('\n');
    }
    indent(out, level + 1);
    out.push_str("],\n");

    if cmd.combine_shorts {
        indent(out, level + 1);
        out.push_str("\"combine_shorts\": true,\n");
    }

    if let Some(dotenv) = &cmd.dotenv {
        indent(out, level + 1);
        out.push_str("\"dotenv\": ");
        out.push_str(&escape_json_str(dotenv));
        out.push_str(",\n");
    }

    if let Some(before) = &cmd.before_hook {
        indent(out, level + 1);
        out.push_str("\"before_hook\": ");
        out.push_str(&escape_json_str(before));
        out.push_str(",\n");
    }

    if let Some(after) = &cmd.after_hook {
        indent(out, level + 1);
        out.push_str("\"after_hook\": ");
        out.push_str(&escape_json_str(after));
        out.push_str(",\n");
    }

    if let Some(tools) = &cmd.require_tools {
        indent(out, level + 1);
        out.push_str("\"require_tools\": [\n");
        for (i, tool) in tools.iter().enumerate() {
            indent(out, level + 2);
            out.push_str(&escape_json_str(tool));
            if i + 1 < tools.len() {
                out.push(',');
            }
            out.push('\n');
        }
        indent(out, level + 1);
        out.push_str("],\n");
    }

    if !cmd.metadata.is_empty() {
        indent(out, level + 1);
        out.push_str("\"metadata\": {\n");
        let keys: Vec<_> = cmd.metadata.keys().collect();
        for (i, k) in keys.iter().enumerate() {
            indent(out, level + 2);
            out.push_str(&escape_json_str(k));
            out.push_str(": ");
            format_opt_str(out, &cmd.metadata[*k]);
            if i + 1 < keys.len() {
                out.push(',');
            }
            out.push('\n');
        }
        indent(out, level + 1);
        out.push_str("},\n");
    }

    indent(out, level + 1);
    out.push_str("\"command_fn\": ");
    format_opt_str(out, &cmd.command_fn);
    out.push('\n');

    indent(out, level);
    out.push('}');
}
