use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub const ARGCFILE_NAMES: &[&str] = &[
    "Argcfile.sh",
    "Argcfile",
    "argcfile.sh",
    "argcfile",
    "ARGCFILE.sh",
    "ARGCFILE",
];

pub fn search_argcfile() -> Option<PathBuf> {
    let mut current = env::current_dir().ok()?;
    loop {
        for name in ARGCFILE_NAMES {
            let candidate = current.join(name);
            if candidate.is_file() {
                return Some(candidate);
            }
        }
        if !current.pop() {
            break;
        }
    }
    None
}

pub fn get_shell_path() -> Result<String, String> {
    if let Ok(env_shell) = env::var("ARGC_SHELL_PATH") {
        if Path::new(&env_shell).is_file() {
            return Ok(env_shell);
        } else {
            return Err(format!("Invalid ARGC_SHELL_PATH, '{}' does not exist", env_shell));
        }
    }

    if let Ok(path_var) = env::var("PATH") {
        for dir in env::split_paths(&path_var) {
            let candidate = dir.join("bash");
            if candidate.is_file() {
                return Ok(candidate.to_string_lossy().to_string());
            }
            #[cfg(windows)]
            {
                let candidate_exe = dir.join("bash.exe");
                if candidate_exe.is_file() {
                    return Ok(candidate_exe.to_string_lossy().to_string());
                }
            }
        }
    }

    Ok("/bin/bash".to_string())
}
EOF
"}

