{"command":"cat <<'EOF' > src/export.rs
use crate::ast::*;

pub fn export_command_json(cmd: &Command) -> String {
    let mut out = String::new();
    format_command(&mut out, cmd, 0);
    out
}

fn indent(out: &mut String, level: usize) {
    for _ in 0..level {
        out.push_str("  ");
    }
}

fn escape_json_str(s: &str) -> String {
    let mut out = String::new();
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn format_opt_str(out: &mut String, val: &Option<String>) {
    match val {
        Some(s) => out.push_str(&escape_json_str(s)),
        None => out.push_str("null"),
    }
}

fn format_default_value(out: &mut String, level: usize, def: &Option<DefaultValue>) {
    match def {
        None => out.push_str("null"),
        Some(DefaultValue::Value(v)) => {
            out.push_str("{\n");
            indent(out, level + 1);
            out.push_str("\"type\": \"Value\",\n");
            indent(out, level + 1);
            out.push_str("\"value\": ");
            out.push_str(&escape_json_str(v));
            out.push('\n');
            indent(out, level);
            out.push('}');
        }
        Some(DefaultValue::Fn(f)) => {
            out.push_str("{\n");
            indent(out, level + 1);
            out.push_str("\"type\": \"Fn\",\n");
            indent(out, level + 1);
            out.push_str("\"value\": ");
            out.push_str(&escape_json_str(f));
            out.push('\n');
            indent(out, level);
            out.push('}');
        }
    }
}

fn format_choice_value(out: &mut String, level: usize, choice: &Option<ChoiceValue>) {
    match choice {
        None => out.push_str("null"),
        Some(ChoiceValue::Values(vals)) => {
            out.push_str("{\n");
            indent(out, level + 1);
            out.push_str("\"type\": \"Values\",\n");
            indent(out, level + 1);
            if vals.is_empty() {
                out.push_str("\"data\": []\n");
            } else {
                out.push_str("\"data\": [\n");
                for (i, v) in vals.iter().enumerate() {
                    indent(out, level + 2);
                    out.push_str(&escape_json_str(v));
                    if i + 1 < vals.len() {
                        out.push(',');
                    }
                    out.push('\n');
                }
                indent(out, level + 1);
                out.push_str("]\n");
            }
            indent(out, level);
            out.push('}');
        }
        Some(ChoiceValue::Fn(f, validate)) => {
            out.push_str("{\n");
            indent(out, level + 1);
            out.push_str("\"type\": \"Fn\",\n");
            indent(out, level + 1);
            out.push_str("\"data\": [\n");
            indent(out, level + 2);
            out.push_str(&escape_json_str(f));
            out.push_str(",\n");
            indent(out, level + 2);
            if *validate {
                out.push_str("true\n");
            } else {
                out.push_str("false\n");
            }
            indent(out, level + 1);
            out.push_str("]\n");
            indent(out, level);
            out.push('}');
        }
    }
}

fn format_flag_option(out: &mut String, fo: &FlagOption, level: usize) {
    indent(out, level);
    out.push_str("{\n");

    indent(out, level + 1);
    out.push_str("\"id\": ");
    out.push_str(&escape_json_str(&fo.id));
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"long_name\": ");
    format_opt_str(out, &fo.long_name);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"short_name\": ");
    format_opt_str(out, &fo.short_name);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"describe\": ");
    out.push_str(&escape_json_str(&fo.describe));
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"flag\": ");
    out.push_str(if fo.flag { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    if fo.notations.is_empty() {
        out.push_str("\"notations\": [],\n");
    } else {
        out.push_str("\"notations\": [\n");
        for (i, n) in fo.notations.iter().enumerate() {
            indent(out, level + 2);
            out.push_str(&escape_json_str(n));
            if i + 1 < fo.notations.len() {
                out.push(',');
            }
            out.push('\n');
        }
        indent(out, level + 1);
        out.push_str("],\n");
    }

    indent(out, level + 1);
    out.push_str("\"required\": ");
    out.push_str(if fo.required { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"multiple_values\": ");
    out.push_str(if fo.multiple_values { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"multiple_occurs\": ");
    out.push_str(if fo.multiple_occurs { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"num_args\": [\n");
    indent(out, level + 2);
    out.push_str(&fo.num_args.0.to_string());
    out.push_str(",\n");
    indent(out, level + 2);
    out.push_str(&fo.num_args.1.to_string());
    out.push('\n');
    indent(out, level + 1);
    out.push_str("],\n");

    indent(out, level + 1);
    out.push_str("\"delimiter\": ");
    format_opt_str(out, &fo.delimiter);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"terminated\": ");
    out.push_str(if fo.terminated { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"prefixed\": ");
    out.push_str(if fo.prefixed { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"assigned\": ");
    out.push_str(if fo.assigned { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"default\": ");
    format_default_value(out, level + 1, &fo.default);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"choice\": ");
    format_choice_value(out, level + 1, &fo.choice);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"env\": ");
    format_opt_str(out, &fo.env);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"inherited\": ");
    out.push_str(if fo.inherited { "true" } else { "false" });
    out.push('\n');

    indent(out, level);
    out.push('}');
}

fn format_positional(out: &mut String, pos: &Positional, level: usize) {
    indent(out, level);
    out.push_str("{\n");

    indent(out, level + 1);
    out.push_str("\"id\": ");
    out.push_str(&escape_json_str(&pos.id));
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"describe\": ");
    out.push_str(&escape_json_str(&pos.describe));
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"notation\": ");
    out.push_str(&escape_json_str(&pos.notation));
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"required\": ");
    out.push_str(if pos.required { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"multiple\": ");
    out.push_str(if pos.multiple { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"delimiter\": ");
    format_opt_str(out, &pos.delimiter);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"terminated\": ");
    out.push_str(if pos.terminated { "true" } else { "false" });
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"default\": ");
    format_default_value(out, level + 1, &pos.default);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"choice\": ");
    format_choice_value(out, level + 1, &pos.choice);
    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"env\": ");
    format_opt_str(out, &pos.env);
