    indent(out, level);
    out.push('}');
}

fn format_env(out: &mut String, env: &Env, level: usize) {
    indent(out, level);
    out.push_str("{\n");

    indent(out, level + 1);
    out.push_str("\"id\": ");
    out.push_str(&escape_json_str(&env.id));
