        indent(out, level + 1);
        out.push_str("\"combine_shorts\": true,\n");
    }

    if let Some(dotenv) = &cmd.dotenv {
        indent(out, level + 1);
        out.push_str("\"dotenv\": ");
        out.push_str(&escape_json_str(dotenv));
        out.push_str(",\n");
    }

    if let Some(before) = &cmd.before_hook {
        indent(out, level + 1);
        out.push_str("\"before_hook\": ");
        out.push_str(&escape_json_str(before));
        out.push_str(",\n");
    }

    if let Some(after) = &cmd.after_hook {
        indent(out, level + 1);
        out.push_str("\"after_hook\": ");
        out.push_str(&escape_json_str(after));
        out.push_str(",\n");
    }

