        indent(out, level + 1);
        out.push_str("\"require_tools\": [\n");
        for (i, tool) in tools.iter().enumerate() {
            indent(out, level + 2);
            out.push_str(&escape_json_str(tool));
            if i + 1 < tools.len() {
                out.push(',');
            }
            out.push('\n');
        }
        indent(out, level + 1);
        out.push_str("],\n");
    }

