    out.push_str(",\n");

    indent(out, level + 1);
    out.push_str("\"inherited\": ");
    out.push_str(if fo.inherited { "true" } else { "false" });
    out.push('\n');

    indent(out, level);
    out.push('}');
}

fn format_positional(out: &mut String, pos: &Positional, level: usize) {
    indent(out, level);
    out.push_str("{\n");

    indent(out, level + 1);
    out.push_str("\"id\": ");
    out.push_str(&escape_json_str(&pos.id));
