    let mut after_hook: Option<String> = None;
    let mut main_fn_exists = false;

    let mut current_block = TagBlock::default();
    let mut in_cmd_block = false;
    let mut active_target: Option<ActiveDescTarget> = None;

    let mut i = 0;
    while i < lines.len() {
        let raw_line = lines[i];
        let line = raw_line.trim();

        if line.starts_with('#') {
            if i == 0 && (line.starts_with("#!") || line.starts_with("#/")) {
                i += 1;
                continue;
            }

            let comment_text = if line.starts_with("# ") {
                &raw_line[raw_line.find('#').unwrap() + 2..]
            } else if line.starts_with('#') {
                &raw_line[raw_line.find('#').unwrap() + 1..]
            } else {
                ""
            };

            let trimmed_comment = comment_text.trim_start();

            if trimmed_comment.starts_with('@') {
                active_target = None;
                parse_tag_line(
                    trimmed_comment,
                    &mut current_block,
                    &mut in_cmd_block,
                    &mut root_describe,
                    &mut root_version,
                    &mut root_combine_shorts,
                    &mut root_dotenv,
                    &mut root_require_tools,
                    &mut root_metadata,
                    &mut root_flags_options,
                    &mut root_positionals,
                    &mut root_envs,
                    &mut active_target,
                );
            } else if let Some(target) = active_target {
                let desc_ref = match target {
                    ActiveDescTarget::Root => &mut root_describe,
                    ActiveDescTarget::Block => &mut current_block.describe,
                    ActiveDescTarget::Flag(idx) => &mut current_block.flags[idx].describe,
                    ActiveDescTarget::Option(idx) => &mut current_block.options[idx].describe,
                    ActiveDescTarget::Pos(idx) => &mut current_block.positionals[idx].describe,
                    ActiveDescTarget::Env(idx) => &mut current_block.envs[idx].describe,
                };

                if comment_text.trim().is_empty() {
                    if !desc_ref.is_empty() {
                        desc_ref.push_str("\n\n");
                    }
                } else {
                    if !desc_ref.is_empty() && !desc_ref.ends_with('\n') && !desc_ref.ends_with("\n\n") {
                        desc_ref.push('\n');
                    }
                    desc_ref.push_str(comment_text);
                }
            } else if !in_cmd_block && subcommands_flat.is_empty() {
                if comment_text.trim().is_empty() {
                    if !root_describe.is_empty() {
                        root_describe.push_str("\n\n");
                    }
                } else {
                    if !root_describe.is_empty() && !root_describe.ends_with('\n') && !root_describe.ends_with("\n\n") {
                        root_describe.push('\n');
                    }
                    root_describe.push_str(comment_text);
                }
            } else {
                if comment_text.trim().is_empty() {
                    if !current_block.describe.is_empty() {
                        current_block.describe.push_str("\n\n");
                    }
                } else {
                    if !current_block.describe.is_empty() && !current_block.describe.ends_with('\n') && !current_block.describe.ends_with("\n\n") {
                        current_block.describe.push('\n');
                    }
                    current_block.describe.push_str(comment_text);
                }
            }
            i += 1;
            continue;
        }

        active_target = None;

        if let Some(fn_name) = parse_fn_definition(line) {
            if fn_name == "_argc_before" {
                before_hook = Some("_argc_before".to_string());
                current_block = TagBlock::default();
                in_cmd_block = false;
            } else if fn_name == "_argc_after" {
                after_hook = Some("_argc_after".to_string());
                current_block = TagBlock::default();
                in_cmd_block = false;
            } else if fn_name == "main" {
                main_fn_exists = true;
                if in_cmd_block {
                    let cmd = build_command_from_block(&fn_name, fn_name.clone(), &mut current_block);
                    subcommands_flat.push((fn_name, cmd));
                    in_cmd_block = false;
                } else {
                    root_flags_options.extend(current_block.flags.drain(..));
                    root_flags_options.extend(current_block.options.drain(..));
                    root_positionals.extend(current_block.positionals.drain(..));
                    root_envs.extend(current_block.envs.drain(..));
                }
            } else if in_cmd_block || fn_name.contains("::") {
                let cmd_name = if let Some(last) = fn_name.split("::").last() {
                    last.to_string()
                } else {
                    fn_name.clone()
                };
                let cmd = build_command_from_block(&cmd_name, fn_name.clone(), &mut current_block);
                subcommands_flat.push((fn_name, cmd));
                in_cmd_block = false;
            } else {
                root_flags_options.extend(current_block.flags.drain(..));
                root_flags_options.extend(current_block.options.drain(..));
                root_positionals.extend(current_block.positionals.drain(..));
                root_envs.extend(current_block.envs.drain(..));
                current_block = TagBlock::default();
            }
        }

        i += 1;
    }

    root_flags_options.extend(current_block.flags.drain(..));
    root_flags_options.extend(current_block.options.drain(..));
    root_positionals.extend(current_block.positionals.drain(..));
    root_envs.extend(current_block.envs.drain(..));

    let mut root_subcommands = build_subcommand_tree(subcommands_flat);

    let inherit_flag_options = root_metadata.contains_key("inherit-flag-options");
    if inherit_flag_options {
        inherit_flags_options_recursive(&root_flags_options, &mut root_subcommands);
    }

    add_default_flags_root(&mut root_flags_options);
    add_default_flags_subcommands(&mut root_subcommands);

    Command {
        name: script_name,
        describe: root_describe.trim().to_string(),
        version: root_version,
        aliases: Vec::new(),
        flag_options: root_flags_options,
        positionals: root_positionals,
        envs: root_envs,
        subcommands: root_subcommands,
        combine_shorts: root_combine_shorts,
        dotenv: root_dotenv,
        before_hook,
        after_hook,
        require_tools: root_require_tools,
        metadata: root_metadata,
        command_fn: if main_fn_exists {
            Some("main".to_string())
        } else {
            None
        },
    }
}

fn parse_fn_definition(line: &str) -> Option<String> {
    let line = line.trim();
    if line.is_empty() {
        return None;
    }

    let mut s = line;
    if s.starts_with("function ") {
        s = s["function ".len()..].trim();
    }

    if let Some(pos) = s.find('(') {
        let fn_name = s[..pos].trim();
        if !fn_name.is_empty() && is_valid_fn_name(fn_name) {
            return Some(fn_name.to_string());
        }
    } else if let Some(pos) = s.find('{') {
        let fn_name = s[..pos].trim();
        if !fn_name.is_empty() && is_valid_fn_name(fn_name) {
            return Some(fn_name.to_string());
        }
    }

    None
}

fn is_valid_fn_name(s: &str) -> bool {
    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == ':')
}

fn parse_tag_line(
    line: &str,
    block: &mut TagBlock,
    in_cmd_block: &mut bool,
    root_describe: &mut String,
    root_version: &mut Option<String>,
    root_combine_shorts: &mut bool,
    root_dotenv: &mut Option<String>,
    root_require_tools: &mut Option<Vec<String>>,
    root_metadata: &mut BTreeMap<String, Option<String>>,
    root_flags_options: &mut Vec<FlagOption>,
    root_positionals: &mut Vec<Positional>,
    root_envs: &mut Vec<Env>,
    active_target: &mut Option<ActiveDescTarget>,
) {
    let tag_str = line.trim_start_matches('@');
    let mut parts = tag_str.splitn(2, |c: char| c.is_whitespace());
    let tag_name = parts.next().unwrap_or("");
    let tag_body = parts.next().unwrap_or("").trim();

    match tag_name {
        "describe" | "doc" => {
            if *in_cmd_block {
                block.describe = tag_body.to_string();
                *active_target = Some(ActiveDescTarget::Block);
            } else if root_describe.is_empty() {
                *root_describe = tag_body.to_string();
                *active_target = Some(ActiveDescTarget::Root);
            } else {
                block.describe = tag_body.to_string();
                *active_target = Some(ActiveDescTarget::Block);
            }
        }
        "cmd" | "command" => {
            if *in_cmd_block {
                // Flush previous block items to root if any?
            } else {
                // Flush pending items defined before @cmd to root
                root_flags_options.extend(block.flags.drain(..));
                root_flags_options.extend(block.options.drain(..));
                root_positionals.extend(block.positionals.drain(..));
                root_envs.extend(block.envs.drain(..));
            }
            *in_cmd_block = true;
            if !tag_body.is_empty() {
                block.describe = tag_body.to_string();
                *active_target = Some(ActiveDescTarget::Block);
            }
        }
        "alias" => {
            for a in tag_body.split_whitespace() {
                block.aliases.push(a.to_string());
            }
        }
        "flag" => {
            if let Some(fo) = parse_flag(tag_body) {
                block.flags.push(fo);
                let idx = block.flags.len() - 1;
                *active_target = Some(ActiveDescTarget::Flag(idx));
            }
        }
        "option" => {
            if let Some(fo) = parse_option(tag_body) {
                block.options.push(fo);
                let idx = block.options.len() - 1;
                *active_target = Some(ActiveDescTarget::Option(idx));
            }
        }
        "arg" => {
            if let Some(pos) = parse_arg(tag_body) {
                block.positionals.push(pos);
                let idx = block.positionals.len() - 1;
                *active_target = Some(ActiveDescTarget::Pos(idx));
            }
        }
        "env" => {
            if let Some(env) = parse_env(tag_body) {
                block.envs.push(env);
                let idx = block.envs.len() - 1;
                *active_target = Some(ActiveDescTarget::Env(idx));
            }
        }
        "meta" => {
            let mut meta_parts = tag_body.splitn(2, |c: char| c.is_whitespace());
            let k = meta_parts.next().unwrap_or("").trim();
            let v = meta_parts.next().unwrap_or("").trim();

            match k {
                "version" => {
                    *root_version = Some(v.to_string());
                    root_metadata.insert("version".to_string(), Some(v.to_string()));
                }
                "combine-shorts" => {
                    *root_combine_shorts = true;
                    block.metadata.insert("combine-shorts".to_string(), None);
                    root_metadata.insert("combine-shorts".to_string(), None);
                }
                "dotenv" => {
                    let file = if v.is_empty() { ".env" } else { v };
                    *root_dotenv = Some(file.to_string());
                    let val = if v.is_empty() { None } else { Some(v.to_string()) };
                    block.metadata.insert("dotenv".to_string(), val.clone());
                    root_metadata.insert("dotenv".to_string(), val);
                }
                "require-tools" => {
                    let tools: Vec<String> = v
                        .split(|c| c == ',' || c == ' ')
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string())
                        .collect();
                    if *in_cmd_block {
                        block.metadata.insert("require-tools".to_string(), Some(v.to_string()));
                    } else {
                        *root_require_tools = Some(tools.clone());
                        root_metadata.insert("require-tools".to_string(), Some(v.to_string()));
                    }
                }
                "default-subcommand" => {
                    block.metadata.insert("default-subcommand".to_string(), None);
                }
                "inherit-flag-options" => {
                    root_metadata.insert("inherit-flag-options".to_string(), None);
                }
                _ => {
                    let val = if v.is_empty() { None } else { Some(v.to_string()) };
                    if *in_cmd_block {
                        block.metadata.insert(k.to_string(), val.clone());
                    }
                    root_metadata.insert(k.to_string(), val);
                }
            }
        }
        _ => {}
    }
}

fn parse_flag(body: &str) -> Option<FlagOption> {
    let mut fo = FlagOption {
        id: String::new(),
        long_name: None,
        short_name: None,
        describe: String::new(),
        flag: true,
        notations: Vec::new(),
        required: false,
        multiple_values: false,
        multiple_occurs: false,
        num_args: (0, 0),
        delimiter: None,
        terminated: false,
        prefixed: false,
        assigned: false,
        default: None,
        choice: None,
        env: None,
        inherited: false,
    };

    let parts: Vec<&str> = body.split_whitespace().collect();
    if parts.is_empty() {
        return None;
    }

    let mut idx = 0;
    while idx < parts.len() {
        let p = parts[idx];
        if p.starts_with('-') || p.starts_with('+') {
            if p.contains('*') {
                fo.multiple_occurs = true;
            }
            let clean_p = p.trim_matches('*');

            if clean_p.starts_with("--") {
                fo.long_name = Some(clean_p.to_string());
                if fo.id.is_empty() {
                    fo.id = clean_p[2..].to_string();
                }
            } else if clean_p.starts_with('+') {
                fo.long_name = Some(clean_p.to_string());
                if fo.id.is_empty() {
                    fo.id = format!("plus_{}", &clean_p[1..]);
                }
            } else if clean_p.starts_with('-') {
                if fo.short_name.is_none() && clean_p.len() == 2 {
                    fo.short_name = Some(clean_p.to_string());
                } else if fo.long_name.is_none() {
                    fo.long_name = Some(clean_p.to_string());
                    if fo.id.is_empty() {
                        fo.id = clean_p[1..].to_string();
                    }
                }
            }
            idx += 1;
        } else if p == "$$" || p.starts_with('$') {
            if p == "$$" {
                fo.env = Some(fo.id.to_uppercase());
            } else {
                fo.env = Some(p[1..].to_string());
            }
            idx += 1;
        } else {
            fo.describe = parts[idx..].join(" ");
            break;
        }
    }

    Some(fo)
}

fn parse_option(body: &str) -> Option<FlagOption> {
    let mut fo = FlagOption {
        id: String::new(),
        long_name: None,
        short_name: None,
        describe: String::new(),
        flag: false,
        notations: Vec::new(),
        required: false,
        multiple_values: false,
        multiple_occurs: false,
        num_args: (1, 1),
        delimiter: None,
        terminated: false,
        prefixed: false,
        assigned: false,
        default: None,
        choice: None,
        env: None,
        inherited: false,
    };

    let parts: Vec<&str> = body.split_whitespace().collect();
    if parts.is_empty() {
        return None;
    }

    let mut idx = 0;
    while idx < parts.len() {
        let p = parts[idx];
        if p.starts_with('-') || p.starts_with('+') {
            let mut param_spec = p;

            if param_spec.contains('*') {
                fo.multiple_occurs = true;
            }
            if param_spec.contains('+') && !param_spec.starts_with('+') {
                fo.required = true;
                fo.multiple_occurs = true;
            }
            if param_spec.contains('!') {
                fo.required = true;
            }
            if param_spec.contains(',') {
                fo.delimiter = Some(",".to_string());
                fo.multiple_values = true;
            }
            if param_spec.contains('~') {
                fo.terminated = true;
                fo.num_args = (1, 32767);
                fo.multiple_values = true;
            }

            if let Some(choice_idx) = param_spec.find('[') {
                let choice_str = &param_spec[choice_idx..];
                parse_choice_or_default_str(choice_str, &mut fo.default, &mut fo.choice);
                param_spec = &param_spec[..choice_idx];
            } else if let Some(eq_idx) = param_spec.find('=') {
                let def_str = &param_spec[eq_idx + 1..];
                if def_str.starts_with('`') && def_str.ends_with('`') {
                    fo.default = Some(DefaultValue::Fn(def_str[1..def_str.len() - 1].to_string()));
                } else {
                    fo.default = Some(DefaultValue::Value(def_str.to_string()));
                }
                param_spec = &param_spec[..eq_idx];
            }

            let clean_p = param_spec.trim_matches(|c| c == '*' || c == '+' || c == '!' || c == ',' || c == '~');

            if clean_p.starts_with("--") {
                fo.long_name = Some(clean_p.to_string());
                if fo.id.is_empty() {
                    fo.id = clean_p[2..].to_string();
                }
            } else if clean_p.starts_with('+') {
                fo.long_name = Some(clean_p.to_string());
                if fo.id.is_empty() {
                    fo.id = format!("plus_{}", &clean_p[1..]);
                }
            } else if clean_p.starts_with('-') {
                if fo.short_name.is_none() && clean_p.len() == 2 {
                    fo.short_name = Some(clean_p.to_string());
                } else if fo.long_name.is_none() {
                    fo.long_name = Some(clean_p.to_string());
                    if fo.id.is_empty() {
                        fo.id = clean_p[1..].to_string();
                    }
                }
            }
            idx += 1;
        } else if p.starts_with('<') {
            while idx < parts.len() && parts[idx].starts_with('<') {
                let n_str = parts[idx];
                if n_str.contains('*') {
                    fo.multiple_values = true;
                    fo.num_args = (0, 32767);
                } else if n_str.contains('+') {
                    fo.multiple_values = true;
                    fo.num_args = (1, 32767);
                } else if n_str.contains('?') {
                    fo.num_args = (0, 1);
                }
                let clean_n = n_str.trim_matches(|c| c == '<' || c == '>' || c == '*' || c == '+' || c == '?' || c == '~');
                fo.notations.push(clean_n.to_string());
                idx += 1;
            }
        } else if p == "$$" || p.starts_with('$') {
            if p == "$$" {
                fo.env = Some(fo.id.to_uppercase());
            } else {
                fo.env = Some(p[1..].to_string());
            }
            idx += 1;
        } else {
            fo.describe = parts[idx..].join(" ");
            break;
        }
    }

    if fo.notations.is_empty() {
        fo.notations.push(fo.id.to_uppercase());
    }

    Some(fo)
}

fn parse_arg(body: &str) -> Option<Positional> {
    let parts: Vec<&str> = body.split_whitespace().collect();
    if parts.is_empty() {
        return None;
    }

    let mut arg_spec = parts[0];
    let mut pos = Positional {
        id: String::new(),
        describe: String::new(),
        notation: String::new(),
        required: false,
        multiple: false,
        delimiter: None,
        terminated: false,
        default: None,
        choice: None,
        env: None,
    };

    if arg_spec.contains('*') {
        pos.multiple = true;
    }
    if arg_spec.contains('+') {
        pos.required = true;
        pos.multiple = true;
    }
    if arg_spec.contains('!') {
        pos.required = true;
    }
    if arg_spec.contains(',') {
        pos.delimiter = Some(",".to_string());
        pos.multiple = true;
    }
    if arg_spec.contains('~') {
        pos.terminated = true;
        pos.multiple = true;
    }

    if let Some(choice_idx) = arg_spec.find('[') {
        let choice_str = &arg_spec[choice_idx..];
        parse_choice_or_default_str(choice_str, &mut pos.default, &mut pos.choice);
        arg_spec = &arg_spec[..choice_idx];
    } else if let Some(eq_idx) = arg_spec.find('=') {
        let def_str = &arg_spec[eq_idx + 1..];
        if def_str.starts_with('`') && def_str.ends_with('`') {
            pos.default = Some(DefaultValue::Fn(def_str[1..def_str.len() - 1].to_string()));
        } else {
            pos.default = Some(DefaultValue::Value(def_str.to_string()));
        }
        arg_spec = &arg_spec[..eq_idx];
    }

    let clean_id = arg_spec.trim_matches(|c| c == '*' || c == '+' || c == '!' || c == ',' || c == '~');
    pos.id = clean_id.to_string();
    pos.notation = clean_id.to_uppercase();

    let mut idx = 1;
    while idx < parts.len() {
        let p = parts[idx];
        if p.starts_with('<') && p.ends_with('>') {
            pos.notation = p[1..p.len() - 1].to_string();
            idx += 1;
        } else if p == "$$" || p.starts_with('$') {
            if p == "$$" {
                pos.env = Some(pos.id.to_uppercase());
            } else {
                pos.env = Some(p[1..].to_string());
            }
            idx += 1;
        } else {
            pos.describe = parts[idx..].join(" ");
            break;
        }
    }

    Some(pos)
}

fn parse_env(body: &str) -> Option<Env> {
    let parts: Vec<&str> = body.split_whitespace().collect();
    if parts.is_empty() {
        return None;
    }

    let mut env_spec = parts[0];
    let mut env = Env {
        id: String::new(),
        describe: String::new(),
        required: false,
        default: None,
        choice: None,
        inherited: false,
    };

    if env_spec.contains('!') {
        env.required = true;
    }

    if let Some(choice_idx) = env_spec.find('[') {
        let choice_str = &env_spec[choice_idx..];
        parse_choice_or_default_str(choice_str, &mut env.default, &mut env.choice);
        env_spec = &env_spec[..choice_idx];
    } else if let Some(eq_idx) = env_spec.find('=') {
        let def_str = &env_spec[eq_idx + 1..];
        if def_str.starts_with('`') && def_str.ends_with('`') {
            env.default = Some(DefaultValue::Fn(def_str[1..def_str.len() - 1].to_string()));
        } else {
            env.default = Some(DefaultValue::Value(def_str.to_string()));
        }
        env_spec = &env_spec[..eq_idx];
    }

    let clean_id = env_spec.trim_matches('!');
    env.id = clean_id.to_string();

    if parts.len() > 1 {
        env.describe = parts[1..].join(" ");
    }

    Some(env)
}

fn parse_choice_or_default_str(
    s: &str,
    default: &mut Option<DefaultValue>,
    choice: &mut Option<ChoiceValue>,
) {
    let inner = s.trim_matches(|c| c == '[' || c == ']');
    if inner.starts_with('`') && inner.ends_with('`') {
        let fn_name = &inner[1..inner.len() - 1];
        *choice = Some(ChoiceValue::Fn(fn_name.to_string(), true));
    } else if inner.starts_with("?`") && inner.ends_with('`') {
        let fn_name = &inner[2..inner.len() - 1];
        *choice = Some(ChoiceValue::Fn(fn_name.to_string(), false));
    } else {
        let mut vals = Vec::new();
        for item in inner.split('|') {
            if item.starts_with('=') {
                let def_val = &item[1..];
                *default = Some(DefaultValue::Value(def_val.to_string()));
                vals.push(def_val.to_string());
            } else {
                vals.push(item.to_string());
            }
        }
        if !vals.is_empty() {
            *choice = Some(ChoiceValue::Values(vals));
        }
    }
}

fn build_command_from_block(
    cmd_name: &str,
    fn_name: String,
    block: &mut TagBlock,
) -> Command {
    let mut aliases = block.aliases.clone();
    let kebab_name = cmd_name.replace('_', "-");
    if kebab_name != cmd_name && !aliases.contains(&kebab_name) {
        aliases.insert(0, kebab_name);
    }

    let mut flag_options = Vec::new();
    flag_options.extend(block.flags.drain(..));
    flag_options.extend(block.options.drain(..));

    let cmd = Command {
        name: cmd_name.to_string(),
        describe: block.describe.trim().to_string(),
        version: None,
        aliases,
        flag_options,
        positionals: block.positionals.drain(..).collect(),
        envs: block.envs.drain(..).collect(),
        subcommands: Vec::new(),
        combine_shorts: false,
        dotenv: None,
        before_hook: None,
        after_hook: None,
        require_tools: if let Some(tools_str) = block.metadata.get("require-tools").and_then(|o| o.as_ref()) {
            Some(
                tools_str
                    .split(|c| c == ',' || c == ' ')
                    .filter(|s| !s.is_empty())
                    .map(|s| s.to_string())
                    .collect(),
            )
        } else {
            None
        },
        metadata: block.metadata.clone(),
        command_fn: Some(fn_name),
    };

    *block = TagBlock::default();
    cmd
}

fn build_subcommand_tree(flat: Vec<(String, Command)>) -> Vec<Command> {
    let mut root_subs: Vec<Command> = Vec::new();

    for (fn_name, cmd) in flat {
        let parts: Vec<&str> = fn_name.split("::").collect();
        if parts.len() <= 1 {
            root_subs.push(cmd);
        } else {
            insert_nested_cmd(&mut root_subs, &parts[..parts.len() - 1], cmd);
        }
    }

    root_subs
}

fn insert_nested_cmd(current_subs: &mut Vec<Command>, parent_parts: &[&str], cmd: Command) {
    if parent_parts.is_empty() {
        current_subs.push(cmd);
        return;
    }

    let parent_name = parent_parts[0];
    if let Some(parent) = current_subs.iter_mut().find(|c| c.name == parent_name) {
        insert_nested_cmd(&mut parent.subcommands, &parent_parts[1..], cmd);
    } else {
        let mut parent = Command {
            name: parent_name.to_string(),
            describe: String::new(),
            version: None,
            aliases: Vec::new(),
            flag_options: Vec::new(),
            positionals: Vec::new(),
            envs: Vec::new(),
            subcommands: Vec::new(),
            combine_shorts: false,
            dotenv: None,
            before_hook: None,
            after_hook: None,
            require_tools: None,
            metadata: BTreeMap::new(),
            command_fn: None,
        };
        insert_nested_cmd(&mut parent.subcommands, &parent_parts[1..], cmd);
        current_subs.push(parent);
    }
}

fn inherit_flags_options_recursive(parent_opts: &[FlagOption], subcommands: &mut [Command]) {
    for sub in subcommands.iter_mut() {
        for parent_opt in parent_opts {
            if parent_opt.id == "help" || parent_opt.id == "version" {
                continue;
            }
            if !sub.flag_options.iter().any(|o| o.id == parent_opt.id) {
                let mut inherited_opt = parent_opt.clone();
                inherited_opt.inherited = true;
                sub.flag_options.push(inherited_opt);
            }
        }
        inherit_flags_options_recursive(parent_opts, &mut sub.subcommands);
    }
}

