        });

        let help_long = if uses_single_hyphen_help { "-help" } else { "--help" };

        if !sub.flag_options.iter().any(|o| o.id == "help") {
            sub.flag_options.push(FlagOption {
                id: "help".to_string(),
                long_name: Some(help_long.to_string()),
                short_name: Some("-h".to_string()),
