        lines.push("ENVIRONMENTS:".to_string());
        for env in &cmd.envs {
            let mut extra = Vec::new();
            if let Some(ChoiceValue::Values(choices)) = &env.choice {
                extra.push(format!("[possible values: {}]", choices.join(", ")));
