        if !flags_map.contains_key(&fo.id) {
            if let Some(DefaultValue::Value(v)) = &fo.default {
                flags_map.insert(fo.id.clone(), vec![v.clone()]);
            }
        }
    }

    let mut missing_reqs = Vec::new();
    for fo in &cmd.flag_options {
        if fo.required && !flags_map.contains_key(&fo.id) {
            if let Some(l) = &fo.long_name {
                let notation = fo.notations.first().cloned().unwrap_or_else(|| fo.id.to_uppercase());
                missing_reqs.push(format!("  {} <{}>", l, notation));
            }
        }
    }

    let mut pos_map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut p_idx = 0;
    for pos in &cmd.positionals {
        if p_idx < pos_vals.len() {
            if pos.multiple {
                let mut remaining = Vec::new();
                while p_idx < pos_vals.len() {
                    remaining.push(pos_vals[p_idx].clone());
                    p_idx += 1;
                }
                pos_map.insert(pos.id.clone(), remaining);
            } else {
                pos_map.insert(pos.id.clone(), vec![pos_vals[p_idx].clone()]);
                p_idx += 1;
            }
        } else if pos.required {
            missing_reqs.push(format!("  <{}>", pos.notation));
        } else if let Some(DefaultValue::Value(v)) = &pos.default {
            pos_map.insert(pos.id.clone(), vec![v.clone()]);
        }
    }

    if p_idx < pos_vals.len() {
        let err_msg = format!("error: unexpected argument `{}` found", pos_vals[p_idx]);
        let out = format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1\n", err_msg);
        return (out, 0);
    }

    if !missing_reqs.is_empty() {
        let err_msg = format!(
            "error: the following required arguments were not provided:\n{}",
            missing_reqs.join("\n")
        );
        let out = format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1\n", err_msg);
        return (out, 0);
    }

    for fo in &cmd.flag_options {
        if let Some(vals) = flags_map.get(&fo.id) {
            if let Some(ChoiceValue::Values(choices)) = &fo.choice {
                for v in vals {
                    if !choices.contains(v) {
                        let notation = fo.notations.first().cloned().unwrap_or_else(|| fo.id.to_uppercase());
                        let err_msg = format!(
                            "error: invalid value `{}` for `<{}>` \n  [possible values: {}]",
                            v,
                            notation,
                            choices.join(", ")
                        );
                        let out = format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1\n", err_msg);
                        return (out, 0);
                    }
                }
            }
        }
    }

    let mut var_lines = Vec::new();

    for fo in &cmd.flag_options {
        if fo.id == "help" || fo.id == "version" {
            continue;
        }
        if let Some(vals) = flags_map.get(&fo.id) {
            let var_name = format!("argc_{}", fo.id);
            if fo.multiple_values || fo.multiple_occurs {
                let formatted_vals: Vec<String> = vals.iter().map(|v| escape_shell_val(v)).collect();
                var_lines.push(format!("{}=( {} )", var_name, formatted_vals.join(" ")));
            } else {
                var_lines.push(format!("{}={}", var_name, escape_shell_val(&vals[0])));
            }
        }
    }

    for pos in &cmd.positionals {
        if let Some(vals) = pos_map.get(&pos.id) {
            let var_name = format!("argc_{}", pos.id);
            if pos.multiple {
                let formatted_vals: Vec<String> = vals.iter().map(|v| escape_shell_val(v)).collect();
                var_lines.push(format!("{}=( {} )", var_name, formatted_vals.join(" ")));
            } else {
                var_lines.push(format!("{}={}", var_name, escape_shell_val(&vals[0])));
            }
        }
    }

    let mut full_with_root = vec![escape_shell_val(&cmd_path[0])];
    full_with_root.extend(full_args.iter().map(|a| escape_shell_val(a)));
    let formatted_full_args = full_with_root;
    var_lines.push(format!("argc__args=( {} )", formatted_full_args.join(" ")));

    let fn_name = cmd.command_fn.as_deref().unwrap_or("");
    var_lines.push(format!("argc__fn={}", fn_name));

    let formatted_pos: Vec<String> = pos_vals.iter().map(|v| escape_shell_val(v)).collect();
    if formatted_pos.is_empty() {
        var_lines.push("argc__positionals=(  )".to_string());
    } else {
        var_lines.push(format!("argc__positionals=( {} )", formatted_pos.join(" ")));
    }

    if let Some(hook) = &cmd.before_hook {
        var_lines.push(format!("{};", hook));
    }
    if let Some(hook) = &cmd.after_hook {
        var_lines.push(format!("{};", hook));
    }

    let mut b64_input = var_lines.join(";");
    b64_input.push(';');
    let b64_str = base64_encode(&b64_input);

    let mut out_str = String::new();
    out_str.push_str(&format!("export ARGC_VARS={}\n", b64_str));

    for line in &var_lines {
        if !line.ends_with(';') {
            out_str.push_str(line);
            out_str.push('\n');
        }
    }

    if let Some(tools) = &cmd.require_tools {
        out_str.push_str(
            r#"_argc_require_tools() {
    local tool missing_tools=()
    for tool in "$@"; do
        if ! command -v "$tool" >/dev/null 2>&1; then
            missing_tools+=("$tool")
        fi
    done
    if [[ "${#missing_tools[@]}" -gt 0 ]]; then
        echo "error: missing tools: ${missing_tools[*]}" >&2
        exit 1
    fi
}
"#,
        );
        out_str.push_str(&format!("_argc_require_tools {}\n\n", tools.join(" ")));
    }

    if let Some(fn_name) = &cmd.command_fn {
        let pos_args_str = formatted_pos.join(" ");
        if pos_args_str.is_empty() {
            out_str.push_str(&format!("{}\n", fn_name));
        } else {
            out_str.push_str(&format!("{} {}\n", fn_name, pos_args_str));
        }
    }

    (out_str, 0)
}

fn escape_shell_val(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    if s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '.' || c == '/' || c == ':' || c == '=' || c == '+' || c == '-') {
        return s.to_string();
    }
    format!("'{}'", s.replace('\'', "'\\''"))
}

fn base64_encode(input: &str) -> String {
    const B64_CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let bytes = input.as_bytes();
    let mut out = String::new();

    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes[i] as u32;
        let b1 = if i + 1 < bytes.len() { bytes[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < bytes.len() { bytes[i + 2] as u32 } else { 0 };

        let triple = (b0 << 16) | (b1 << 8) | b2;

        out.push(B64_CHARS[((triple >> 18) & 0x3F) as usize] as char);
        out.push(B64_CHARS[((triple >> 12) & 0x3F) as usize] as char);

        if i + 1 < bytes.len() {
            out.push(B64_CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            out.push('=');
        }

        if i + 2 < bytes.len() {
            out.push(B64_CHARS[(triple & 0x3F) as usize] as char);
        } else {
            out.push('=');
        }

        i += 3;
    }

    out
}

fn format_help(cmd: &Command, cmd_path: &[String]) -> String {
    let mut lines = Vec::new();

    if !cmd.describe.is_empty() {
        lines.push(cmd.describe.clone());
        lines.push(String::new());
    }

    let mut usage = format!("USAGE: {}", cmd_path.join(" "));
    if !cmd.subcommands.is_empty() {
        usage.push_str(" <COMMAND>");
    } else {
        if !cmd.flag_options.is_empty() {
            usage.push_str(" [OPTIONS]");
        }
        for pos in &cmd.positionals {
            if pos.required {
                usage.push_str(&format!(" <{}>", pos.notation));
            } else {
                usage.push_str(&format!(" [{}]", pos.notation));
            }
        }
    }
    lines.push(usage);

    if !cmd.subcommands.is_empty() {
        lines.push(String::new());
        lines.push("COMMANDS:".to_string());
        for sub in &cmd.subcommands {
            let mut name_str = sub.name.clone();
            if !sub.aliases.is_empty() {
                name_str.push_str(&format!(" [aliases: {}]", sub.aliases.join(", ")));
            }
            if sub.describe.is_empty() {
                lines.push(format!("  {}", name_str));
            } else {
                lines.push(format!("  {:10}  {}", name_str, sub.describe));
            }
        }
    }

    if !cmd.positionals.is_empty() {
        lines.push(String::new());
        lines.push("ARGS:".to_string());
        for pos in &cmd.positionals {
            let name_str = if pos.required {
                format!("<{}>", pos.notation)
            } else {
                format!("[{}]", pos.notation)
            };
            if pos.describe.is_empty() {
                lines.push(format!("  {}", name_str));
            } else {
                lines.push(format!("  {:10}  {}", name_str, pos.describe));
            }
        }
    }

    if !cmd.flag_options.is_empty() {
        lines.push(String::new());
        lines.push("OPTIONS:".to_string());
        for fo in &cmd.flag_options {
            let mut opt_str = String::new();
            if let Some(s) = &fo.short_name {
                opt_str.push_str(s);
            }
            if fo.short_name.is_some() && fo.long_name.is_some() {
                opt_str.push_str(", ");
            } else if fo.short_name.is_none() {
                opt_str.push_str("    ");
            }
            if let Some(l) = &fo.long_name {
                opt_str.push_str(l);
            }
            if !fo.flag {
                if let Some(n) = fo.notations.first() {
                    opt_str.push_str(&format!(" <{}>", n));
                }
            }
            if fo.describe.is_empty() {
                lines.push(format!("  {}", opt_str));
            } else {
                lines.push(format!("  {:20}  {}", opt_str, fo.describe));
            }
        }
    }

    if !cmd.envs.is_empty() {
        lines.push(String::new());
        lines.push("ENVIRONMENTS:".to_string());
        for env in &cmd.envs {
            let mut extra = Vec::new();
            if let Some(ChoiceValue::Values(choices)) = &env.choice {
                extra.push(format!("[possible values: {}]", choices.join(", ")));
            }
            if let Some(DefaultValue::Value(v)) = &env.default {
                extra.push(format!("[default: {}]", v));
            }
            let desc = if extra.is_empty() {
                env.describe.clone()
            } else {
                format!("{} {}", env.describe, extra.join(" ")).trim().to_string()
            };
            lines.push(format!("  {:10}  {}", env.id, desc));
        }
    }

    lines.join("\n")
}
