    let mut full_path = parent_names.to_vec();
    full_path.push(cmd.name.clone());

    let file_basename = full_path.join("-");
    let file_path = out_dir.join(format!("{}.1", file_basename));

    let version = cmd.version.as_deref().unwrap_or("0.0.0");

    let mut roff = String::new();
    roff.push_str(&format!(
        ".TH {} 1  \"{} {}\" \n",
        file_basename.to_uppercase(),
        file_basename,
        version
    ));
    roff.push_str(".SH NAME\n");
    roff.push_str(&format!(
        "{} \\- {}\n",
        file_basename.replace('-', "\\-"),
        cmd.describe
    ));

    roff.push_str(".SH SYNOPSIS\n");
    roff.push_str(&format!("\\fB{}\\fR", full_path.join(" ")));
    if !cmd.subcommands.is_empty() {
        roff.push_str(" <COMMAND>");
    } else {
        if !cmd.flag_options.is_empty() {
            roff.push_str(" [OPTIONS]");
        }
        for pos in &cmd.positionals {
            if pos.required {
                roff.push_str(&format!(" <{}>", pos.notation));
            } else {
                roff.push_str(&format!(" [{}]", pos.notation));
            }
        }
    }
    roff.push('\n');

    if !cmd.subcommands.is_empty() {
        roff.push_str(".SH SUBCOMMANDS\n");
        for sub in &cmd.subcommands {
            roff.push_str(".TP\n");
            let sub_basename = format!("{}-{}", file_basename, sub.name);
            roff.push_str(&format!("{}(1)\n", sub_basename.replace('-', "\\-")));
            roff.push_str(&format!("{}\n", sub.describe));
        }
    }

    if !cmd.flag_options.is_empty() || !cmd.positionals.is_empty() {
        roff.push_str(".SH OPTIONS\n");
        for fo in &cmd.flag_options {
            roff.push_str(".TP\n");
            let mut opt_names = Vec::new();
            if let Some(s) = &fo.short_name {
                opt_names.push(format!("\\fB{}\x5fR", s.replace('-', "\\-")));
            }
            if let Some(l) = &fo.long_name {
                let mut l_str = format!("\\fB{}\x5fR", l.replace('-', "\\-"));
                if !fo.flag {
                    if let Some(n) = fo.notations.first() {
                        l_str.push_str(&format!("=\\fI{}\x5fR", n));
                    }
                }
                opt_names.push(l_str);
            }
            roff.push_str(&opt_names.join(", "));
            roff.push('\n');
            if !fo.describe.is_empty() {
                roff.push_str(".br\n");
                roff.push_str(&format!("{}\n", fo.describe));
            }
        }
        for pos in &cmd.positionals {
            roff.push_str(".TP\n");
            let name_str = if pos.required {
                format!("<\\fI{}\x5fR>", pos.notation)
            } else {
                format!("[\\fI{}\x5fR]", pos.notation)
            };
            roff.push_str(&format!("{}\n", name_str));
            if !pos.describe.is_empty() {
                roff.push_str(".br\n");
                roff.push_str(&format!("{}\n", pos.describe));
            }
        }
    }

