        return Err(format!("Failed to write {}: {}", file_path.display(), e));
    }

    println!("saved {}", file_path.display());

    for sub in &cmd.subcommands {
        generate_cmd_man(sub, &full_path, out_dir)?;
    }

    Ok(())
}
