    s.push_str("# ARGC-BUILD }\n");

    s
}
EOF
"}

{"command":"cat <<'EOF' > src/parallel.rs
use std::env;
use std::process::{Command as ProcessCommand, ExitStatus};
use std::thread;

pub fn parallel(script_path: &str, args: &[String]) -> Result<i32, String> {
    if script_path.is_empty() {
        return Err("Usage: argc --argc-parallel <SCRIPT> <ARGS>...".to_string());
    }

    // Split args by ":::"
    let mut jobs: Vec<Vec<String>> = Vec::new();
    let mut current_job = Vec::new();

    for a in args {
        if a == ":::" {
            if !current_job.is_empty() {
                jobs.push(current_job);
                current_job = Vec::new();
            }
        } else {
            current_job.push(a.clone());
        }
    }
    if !current_job.is_empty() {
        jobs.push(current_job);
    }

    if jobs.is_empty() {
        return Ok(0);
    }

    let argc_vars = env::var("ARGC_VARS").unwrap_or_default();
    let script_abs = std::fs::canonicalize(script_path)
        .unwrap_or_else(|_| std::path::PathBuf::from(script_path));

    let mut handles = Vec::new();

    for job_args in jobs {
        let script_str = script_abs.to_string_lossy().to_string();
        let vars = argc_vars.clone();

        let handle = thread::spawn(move || -> ExitStatus {
            let mut cmd = ProcessCommand::new("bash");

            let job_cmd = job_args.join(" ");
            let eval_stmt = if !vars.is_empty() {
                format!("eval \"$(echo '{}' | base64 -d 2>/dev/null)\" 2>/dev/null; ", vars)
            } else {
                String::new()
            };

            let bash_code = format!("{}source '{}'; {}", eval_stmt, script_str, job_cmd);

            cmd.arg("-c").arg(bash_code);

            cmd.status().unwrap()
        });

        handles.push(handle);
    }

    let mut exit_code = 0;
    for h in handles {
        if let Ok(status) = h.join() {
            if !status.success() {
                exit_code = status.code().unwrap_or(1);
            }
        }
    }

    Ok(exit_code)
}
EOF
"}

