    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && args[1].starts_with("--argc-") {
        let action = &args[1];
        match action.as_str() {
            "--argc-eval" => {
                if args.len() < 3 {
                    println!("echo 'Error: No script file provided'");
                    println!("exit 1");
                    process::exit(0);
                }
                let script_path = Path::new(&args[2]);
                let eval_args = if args.len() > 3 {
                    &args[3..]
                } else {
                    &[]
                };
                let (out, code) = eval::eval(script_path, eval_args);
                print!("{}", out);
                process::exit(code);
            }
            "--argc-export" => {
                if args.len() < 3 {
                    eprintln!("No script file provided");
                    process::exit(1);
                }
                let script_path = Path::new(&args[2]);
                match fs::read_to_string(script_path) {
                    Ok(content) => {
                        let cmd = parser::parse_script(script_path, &content);
                        let json = export::export_command_json(&cmd);
                        println!("{}", json);
                    }
                    Err(e) => {
                        eprintln!("Failed to read script {}: {}", args[2], e);
                        process::exit(1);
                    }
                }
            }
            "--argc-create" => {
                let recipes = if args.len() > 2 {
                    &args[2..]
                } else {
                    &[]
                };
                if let Some(existing) = utils::search_argcfile() {
                    eprintln!("Already exist {}", existing.display());
                    process::exit(1);
                }
                let mut content = String::from("#!/usr/bin/env bash\n\nset -e\n\n");
                for r in recipes {
                    content.push_str(&format!("# @cmd\n{}() {{\n    echo TODO {}\n}}\n\n", r, r));
                }
                content.push_str("# See more details at https://github.com/sigoden/argc\n");
                content.push_str("eval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");

                if let Err(e) = fs::write("Argcfile.sh", content) {
                    eprintln!("Failed to create Argcfile.sh: {}", e);
                    process::exit(1);
                }
                println!("Argcfile.sh has been successfully created.");
            }
            "--argc-run" => {
                if args.len() < 3 {
                    eprintln!("No script file provided");
                    process::exit(1);
                }
                let script = &args[2];
                let run_args = if args.len() > 3 {
                    &args[3..]
                } else {
                    &[]
                };
                let shell = utils::get_shell_path().unwrap_or_else(|_| "/bin/bash".to_string());
                let mut cmd = process::Command::new(shell);
                cmd.arg(script).args(run_args);
                let status = cmd.status().unwrap_or_else(|_| process::exit(1));
                process::exit(status.code().unwrap_or(1));
            }
            "--argc-build" => {
                if args.len() < 3 {
                    eprintln!("No script file provided");
                    process::exit(1);
                }
                let script_path = Path::new(&args[2]);
                let out_path = args.get(3).map(|s| s.as_str());
                if let Err(e) = build::build(script_path, out_path) {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
            "--argc-mangen" => {
                if args.len() < 3 {
                    eprintln!("No script file provided");
                    process::exit(1);
                }
                if args.len() < 4 {
                    eprintln!("No output dir");
                    process::exit(1);
                }
                let script_path = Path::new(&args[2]);
                let out_dir = Path::new(&args[3]);
                if let Err(e) = mangen::mangen(script_path, out_dir) {
                    eprintln!("{}", e);
                    process::exit(1);
                }
            }
            "--argc-completions" => {
                if args.len() < 3 {
                    eprintln!("Usage: argc --argc-completions <SHELL> [CMDS]...");
                    process::exit(1);
                }
                let shell = &args[2];
                let cmds = if args.len() > 3 { &args[3..] } else { &[] };
                match completions::generate_completions(shell, cmds) {
                    Ok(out) => print!("{}", out),
                    Err(e) => {
                        eprintln!("{}", e);
                        process::exit(1);
                    }
                }
            }
            "--argc-compgen" => {
                if args.len() < 4 {
                    process::exit(0);
                }
                let shell = &args[2];
                let script_path = Path::new(&args[3]);
                let comp_args = if args.len() > 4 { &args[4..] } else { &[] };
                let candidates = completions::compgen(shell, script_path, comp_args);
                println!("{}", candidates);
            }
            "--argc-parallel" => {
                if args.len() < 3 {
                    eprintln!("Usage: argc --argc-parallel <SCRIPT> <ARGS>...");
                    process::exit(1);
                }
                let script = &args[2];
                let job_args = if args.len() > 3 { &args[3..] } else { &[] };
                match parallel::parallel(script, job_args) {
                    Ok(code) => process::exit(code),
                    Err(e) => {
                        eprintln!("{}", e);
                        process::exit(1);
                    }
                }
            }
            "--argc-script-path" => {
                if let Some(path) = utils::search_argcfile() {
                    println!("{}", path.display());
                } else {
                    eprintln!("Argcfile not found.");
                    process::exit(1);
                }
            }
            "--argc-shell-path" => {
                match utils::get_shell_path() {
                    Ok(path) => println!("{}", path),
                    Err(err) => {
                        eprintln!("{}", err);
                        process::exit(1);
                    }
                }
            }
            "--argc-help" => {
                print_argc_help();
            }
            "--argc-version" => {
                println!("argc 1.23.0");
            }
            _ => {
                eprintln!("Unknown option `{}`", action);
                process::exit(1);
            }
        }
        return;
    }

    // Default Argcfile runner mode
    if let Some(argcfile) = utils::search_argcfile() {
        let shell = utils::get_shell_path().unwrap_or_else(|_| "/bin/bash".to_string());
        let mut cmd = process::Command::new(shell);
        cmd.arg(argcfile);
        if args.len() > 1 {
            cmd.args(&args[1..]);
        }
        let status = cmd.status().unwrap_or_else(|_| process::exit(1));
        process::exit(status.code().unwrap_or(1));
    } else {
        eprintln!("Argcfile not found, try `argc --argc-help` for help.");
        process::exit(1);
    }
}

fn print_argc_help() {
    print!(
        r#"A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval "$(argc --argc-eval "$0" "$@")"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information

"#
    );
}
EOF
"}

