            }
            s
        }
        _ => String::new(),
    };

    Ok(out)
}

pub fn compgen(_shell: &str, script_path: &Path, args: &[String]) -> String {
    let content = match fs::read_to_string(script_path) {
        Ok(c) => c,
        Err(_) => return String::new(),
    };

    let root_cmd = parser::parse_script(script_path, &content);

    let mut current_cmd = &root_cmd;
    let mut arg_idx = 0;

    while arg_idx < args.len() {
        let arg = &args[arg_idx];
        if arg.starts_with('-') || arg.starts_with('+') {
            break;
        }

        let mut matched_sub = None;
        for sub in &current_cmd.subcommands {
            if sub.name == *arg || sub.aliases.contains(arg) {
                matched_sub = Some(sub);
                break;
            }
        }

        if let Some(sub) = matched_sub {
            current_cmd = sub;
            arg_idx += 1;
        } else {
            break;
        }
    }

    let last_word = args.last().map(|s| s.as_str()).unwrap_or("");

    let mut candidates = Vec::new();

    if last_word.starts_with('-') {
        for fo in &current_cmd.flag_options {
            if let Some(l) = &fo.long_name {
                if fo.describe.is_empty() {
                    candidates.push(l.clone());
                } else {
                    candidates.push(format!("{} ({})", l, fo.describe));
                }
            }
        }
    } else {
        for sub in &current_cmd.subcommands {
            if sub.describe.is_empty() {
                candidates.push(sub.name.clone());
            } else {
                candidates.push(format!("{} ({})", sub.name, sub.describe));
            }
        }
        if !current_cmd.subcommands.is_empty() {
            candidates.push("help (Show help for a command)".to_string());
        }
    }

    candidates.join("\n")
}
