    "elvish",
    "fish",
    "nushell",
    "powershell",
    "xonsh",
    "zsh",
    "tcsh",
];

pub fn generate_completions(shell: &str, cmds: &[String]) -> Result<String, String> {
    if !SUPPORTED_SHELLS.contains(&shell) {
        return Err(format!(
            "The provided shell is either invalid or missing, must be one of {}",
            SUPPORTED_SHELLS.join(",")
        ));
    }

    let mut all_cmds = vec!["argc".to_string()];
    for c in cmds {
        if !all_cmds.contains(c) {
            all_cmds.push(c.clone());
        }
    }

    let cmds_space = all_cmds.join(" ");
    let cmds_quoted_space = all_cmds.iter().map(|c| format!("\"{}\"", c)).collect::<Vec<_>>().join(" ");
    let cmds_quoted_comma = all_cmds.iter().map(|c| format!("\"{}\"", c)).collect::<Vec<_>>().join(",");
    let cmds_quoted_comma_space = all_cmds.iter().map(|c| format!("\"{}\"", c)).collect::<Vec<_>>().join(", ");

    let out = match shell {
        "bash" => r#"_argc_completer() {
    declare -a _argc_completer_words
    _argc_completer_parse_line

    export COMP_WORDBREAKS
    while IFS=$'\n' read -r line; do
        COMPREPLY+=( "$line" )
    done < <(argc --argc-compgen bash "" "${_argc_completer_words[@]}" 2>/dev/null)
}

_argc_completer_parse_line() {
    local line len i char prev_char word unbalance
    line="${COMP_LINE:0:$COMP_POINT}"
    len="${#line}"

    for ((i=0; i<len; i++)); do
        char="${line:i:1}"
        if [[ -n "$unbalance" ]]; then
            word="$word$char"
            if [[  "$unbalance" == "$char" ]]; then
                unbalance=""
            fi
        elif [[ "$char" == " " ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            elif [[ -n "$word" ]]; then
                _argc_completer_words+=( "$word" )
                word=""
            fi
        elif [[ "$char" == "'" || "$char" == '"' ]]; then
            word="$word$char"
            unbalance="$char"
        elif [[ "$char" == "\\" ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            fi
        else
            word="$word$char"
        fi
        prev_char="$char"
    done

    _argc_completer_words+=( "$word" )
}

complete -F _argc_completer -o nospace -o nosort \
    __CMDS_SPACE__
"#.replace("__CMDS_SPACE__", &cmds_space),

        "elvish" => r#"use str

fn argc-completer {|@args|
    var candidates = [(argc --argc-compgen elvish (all (conj [''] (all $args))))]
    all $candidates | each {|candidate| 
        var parts = [(str:split "\t" $candidate)]
        var code-suffix = (if (eq $parts[1] 1) { echo ' ' } else { echo '' })
        var display = (if (eq $parts[3] '') {
            put (styled $parts[2] $parts[4])
        } else {
            put (styled $parts[2] $parts[4])(styled ' ' 'dim white bg-default')(styled '('$parts[3]')' 'dim white')
        })
        edit:complex-candidate $parts[0] &display=$display &code-suffix=$code-suffix
    }
}

all [__CMDS_QUOTED_SPACE__] | 
    each {|cmd| set edit:completion:arg-completer[$cmd] = $argc-completer~ }
"#.replace("__CMDS_QUOTED_SPACE__", &cmds_quoted_space),

        "fish" => r#"function _argc_completer
    set -g _argc_completer_words
    _argc_completer_parse_line

    argc --argc-compgen fish "" $_argc_completer_words
end

function _argc_completer_parse_line
    set -l line (commandline -cp) 
    set -l word ''
    set -l unbalance ''
    set -l prev_char ''

    for i in (seq (string length -- $line))
        set -l char (string sub -s $i -l 1 -- $line)

        if test -n "$unbalance"
            set word "$word$char"
            if test "$unbalance" = "$char"
                set unbalance ''
            end
        else if test "$char" = ' '
            if test "$prev_char" = '\\'
                set word "$word$char"
            else if test -n "$word"
                set -a _argc_completer_words "$word"
                set word ''
            end
        else if test "$char" = "'" -o "$char" = '"'
            set word "$word$char"
            set unbalance "$char"
        else if test "$char" = '\\'
            if test "$prev_char" = '\\'
                set word "$word$char"
            end
        else
            set word "$word$char"
        end

        set prev_char "$char"
    end

    set -a _argc_completer_words "$word"
end


for cmd in __CMDS_SPACE__
    complete -x -k -c $cmd -a "(_argc_completer)"
end
"#.replace("__CMDS_SPACE__", &cmds_space),

        "nushell" => r#"def _argc_completer [args: list<string>] {
    argc --argc-compgen nushell "" ...$args
        | split row "\n"
        | each { |line| $line | split column "\t" value description }
        | flatten 
}

let external_completer = {|spans| 
    _argc_completer $spans
}

$env.config.completions.external.enable = true
$env.config.completions.external.completer = $external_completer
"#.to_string(),

        "powershell" => r#"using namespace System.Management.Automation

$_argc_completer = {
    param($wordToComplete, $commandAst, $cursorPosition)
    $words = @($commandAst.CommandElements | Where { $_.Extent.StartOffset -lt $cursorPosition } | ForEach-Object {
        $word =  $_.ToString() 
        if ($word.Length -gt 2) {
            if (($word.StartsWith('"') -and $word.EndsWith('"')) -or ($word.StartsWith("'") -and $word.EndsWith("'"))) {
                $word = $word.Substring(1, $word.Length - 2)
            }
        }
        return $word
    })
    $emptyS = ''
    if ($PSVersionTable.PSVersion.Major -eq 5) {
        $emptyS = '""'
    }
    $lastElemIndex = -1
    if ($words.Count -lt $commandAst.CommandElements.Count) {
        $lastElemIndex = $words.Count - 1
    }
    if ($commandAst.CommandElements[$lastElemIndex].Extent.EndOffset -lt $cursorPosition) {
        $words += $emptyS
    }
    @((argc --argc-compgen powershell $emptyS $words) -split "`n") | ForEach-Object {
        $parts = ($_ -split "`t")
        if ($parts[1] -eq "1") {
            $value = $parts[0] + " "
        } else {
            $value = $parts[0]
        }
        if ($parts[3] -eq "") {
            $description = "$([char]0x1b)[" + $parts[4] + "m" + $parts[2] + "$([char]0x1b)[0m"
        } else {
            $description = "$([char]0x1b)[" + $parts[4] + "m" + $parts[2] + "$([char]0x1b)[38;5;244m (" + $parts[3] + ")$([char]0x1b)[0m"
        }
        [CompletionResult]::new($value, $description, [CompletionResultType]::ParameterValue, " ")
    }
}

@(__CMDS_QUOTED_COMMA__) | 
    ForEach-Object {
        Register-ArgumentCompleter -Native -ScriptBlock $_argc_completer -CommandName $_
    }
"#.replace("__CMDS_QUOTED_COMMA__", &cmds_quoted_comma),

        "xonsh" => r#"from subprocess import Popen, PIPE
from xonsh.completers.tools import *
from xonsh.completers._aliases import _add_one_completer

@contextual_command_completer
def _argc_completer(context):
    if len(context.args) == 0:
        return
    args = [v.value for v in context.args[0:context.arg_index]]
    args.append(context.raw_prefix)

    if args[0] not in __xonsh__.env['ARGC_XONSH_SCRIPTS']:
        return

    output, _ = Popen(['argc', '--argc-compgen', 'xonsh', '', *args], stdout=PIPE, stderr=PIPE).communicate()
    candidates = output.decode().split('\n')
    candidates.pop()
    result = set()
    skip = 0
    if len(candidates) == 0:
        result.add(RichCompletion(""))
        return result

    for v in candidates:
        parts = v.split('\t')
        value = parts[0]
        if parts[1] == "1":
            value = value + " "
        result.add(RichCompletion(value, display=parts[2], description=parts[3], prefix_len=len(args[-1]), append_closing_quote=False))

    return result

if 'ARGC_XONSH_SCRIPTS' not in __xonsh__.env:
    __xonsh__.env['ARGC_XONSH_SCRIPTS'] = []

if 'argc' not in __xonsh__.completers:
    _add_one_completer('argc', _argc_completer, 'start')

__xonsh__.env['ARGC_XONSH_SCRIPTS'].extend([__CMDS_QUOTED_COMMA_SPACE__])
"#.replace("__CMDS_QUOTED_COMMA_SPACE__", &cmds_quoted_comma_space),

        "zsh" => r#"_argc_completer() {
    local new_words
    _argc_completer_reassemble_words

    local candidates=() values=() displays=() colors display_value
    while IFS=$'\n' read -r line; do
        if [[ "$line" == "" ]]; then line=$'\0'; fi
        candidates+=( "$line" )
    done < <(argc --argc-compgen zsh $'\0' $new_words 2>/dev/null)
    for candidate in ${candidates[@]}; do
        IFS=$'\t' read -r value display color_key color <<< "$candidate"
        colors="$colors:=(#b)($color_key)([ ]## -- *)=0=$color=2:=(#b)($color_key)=0=$color"
        values+=( "${value}" )
        displays+=( "$display" )
    done
    zstyle ":completion:${curcontext}:*" list-colors "${colors:1}:=(#b)(-- *)=0=2"
    _describe "" displays values -Q -S '' -o nosort
}

_argc_completer_reassemble_words() {
    local i cword
    new_words=()
    for ((i=1; i<=$CURRENT; i++)); do
        cword="$words[$i]"
        if [[ "$cword" == "" ]]; then
            new_words+=( $'\0' )
        else
            if [[ "$cword" == *"\\"* ]]; then
                local j char next_char cword_len word
                cword_len="${#cword}"
                for ((j=0; j<$cword_len; j++)); do
                    char="${cword:$j:1}"
                    if [[ "$char" == "\\" ]]; then
                        next_char="${cword:$((j+1)):1}"
                        if [[ "$next_char" == "\\" ]]; then
                            word="$word$char"
                            j=$((j+1))
                        fi
                    else
                        word="$word$char"
                    fi
                done
                cword="$word"
            fi
            new_words+=( "$cword" )
        fi
    done
}

compdef _argc_completer \
    __CMDS_SPACE__
"#.replace("__CMDS_SPACE__", &cmds_space),

