use std::path::{Path, PathBuf};

pub fn build(script_path: &Path, out_path: Option<&str>) -> Result<(), String> {
    let content = match fs::read_to_string(script_path) {
        Ok(c) => c,
        Err(e) => return Err(format!("Failed to read script: {}", e)),
    };

    let root_cmd = parser::parse_script(script_path, &content);

    let mut lines = Vec::new();
    for line in content.lines() {
        if line.contains("argc --argc-eval") {
            break;
        }
        lines.push(line);
    }

    let user_script = lines.join("\n");
    let build_block = generate_build_block(&root_cmd);

    let full_script = format!("{}\n\n{}", user_script.trim_end(), build_block);

    if let Some(target) = out_path {
        let target_path = Path::new(target);
        let final_path = if target.ends_with('/') || target_path.is_dir() {
            let file_name = script_path.file_name().unwrap_or_default();
            target_path.join(file_name)
        } else {
            PathBuf::from(target)
        };

        if let Some(parent) = final_path.parent() {
            let _ = fs::create_dir_all(parent);
        }

        if let Err(e) = fs::write(&final_path, &full_script) {
            return Err(format!("Failed to write script: {}", e));
        }

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&final_path, fs::Permissions::from_mode(0o755));
        }
    } else {
        print!("{}", full_script);
    }

    Ok(())
}

fn generate_build_block(cmd: &Command) -> String {
    let mut s = String::new();
    s.push_str("# ARGC-BUILD {\n");
    s.push_str("# This block was generated by argc (https://github.com/sigoden/argc).\n");
    s.push_str("# Modifying it manually is not recommended\n\n");

    s.push_str(
        r#"_argc_run() {
    if [[ "${1:-}" == "___internal___" ]]; then
        _argc_die "error: unsupported ___internal___ command"
    fi
    if [[ "${OS:-}" == "Windows_NT" ]] && [[ -n "${MSYSTEM:-}" ]]; then
        set -o igncr
    fi
    argc__args=("$(basename "$0" .sh)" "$@")
    argc__positionals=()
    _argc_index=1
    _argc_len="${#argc__args[@]}"
    _argc_required_flag_options=()
    _argc_required_envs=()
    _argc_tools=()
    _argc_parse
    if [ -n "${argc__fn:-}" ]; then
        $argc__fn "${argc__positionals[@]}"
    fi
}

"#,
    );

    s.push_str(&format!(
        r#"_argc_usage() {{
    cat <<-'EOF'
{}
EOF
    exit
}}

"#,
        format_build_usage(cmd)
    ));

    s.push_str(&format!(
        r#"_argc_version() {{
    echo {} {}
    exit
}}

"#,
        cmd.name,
        cmd.version.as_deref().unwrap_or("0.0.0")
    ));

    s.push_str(&generate_cmd_parse(cmd, &cmd.name));

    for sub in &cmd.subcommands {
        s.push_str(&generate_cmd_parse(sub, &format!("{}_{}", cmd.name, sub.name)));
    }

    s.push_str(
        r#"_argc_take_args() {
    _argc_take_args_values=()
    _argc_take_args_len=0
    local param="$1" min="$2" max="$3" signs="$4" delimiter="$5"
    if [[ "$min" -eq 0 ]] && [[ "$max" -eq 0 ]]; then
        return
    fi
    local _argc_take_index=$((_argc_index + 1)) _argc_take_value
    if [[ "$_argc_item" == *=* ]]; then
        _argc_take_args_values=("${_argc_item##*=}")
    else
        while [[ $_argc_take_index -lt $_argc_len ]]; do
            _argc_take_value="${argc__args[_argc_take_index]}"
            if _argc_maybe_flag_option "$signs" "$_argc_take_value"; then
                if [[ "${#_argc_take_value}" -gt 1 ]]; then
                    break
                fi
            fi
            _argc_take_args_values+=("$_argc_take_value")
            _argc_take_args_len=$((_argc_take_args_len + 1))
            if [[ "$_argc_take_args_len" -ge "$max" ]]; then
                break
            fi
            _argc_take_index=$((_argc_take_index + 1))
        done
    fi
    if [[ "${#_argc_take_args_values[@]}" -lt "$min" ]]; then
        _argc_die "error: incorrect number of values for \`$param\`"
    fi
}

_argc_match_positionals() {
    _argc_match_positionals_values=()
    _argc_match_positionals_len=0
    local params=("$@")
    local args_len="${#argc__positionals[@]}"
    if [[ $args_len -eq 0 ]]; then
        return
    fi
    local params_len=$# arg_index=0 param_index=0
    while [[ $param_index -lt $params_len && $arg_index -lt $args_len ]]; do
        local takes=0
        if [[ "${params[param_index]}" -eq 1 ]]; then
            local arg_diff=$((args_len - arg_index)) param_diff=$((params_len - param_index))
            if [[ $arg_diff -gt $param_diff ]]; then
                takes=$((arg_diff - param_diff + 1))
            else
                takes=1
            fi
        else
            takes=1
        fi
        _argc_match_positionals_values+=("$arg_index:$takes")
        arg_index=$((arg_index + takes))
        param_index=$((param_index + 1))
    done
    _argc_match_positionals_len=${#_argc_match_positionals_values[@]}
