    } else {
        s.push_str("    local _argc_subcmds=\"\"\n");
    }

    s.push_str("    while [[ $_argc_index -lt $_argc_len ]]; do\n");
    s.push_str("        _argc_item=\"${argc__args[_argc_index]}\"\n");
    s.push_str("        _argc_key=\"${_argc_item%%=*}\"\n");
    s.push_str("        case \"$_argc_key\" in\n");

    s.push_str("        --help | -help | -h)\n");
    if func_prefix == cmd.name {
        s.push_str("            _argc_usage\n");
    } else {
        s.push_str(&format!("            _argc_usage_{}\n", cmd.name));
    }
    s.push_str("            ;;\n");

    s.push_str("        --version | -version | -V)\n");
    s.push_str("            _argc_version\n");
    s.push_str("            ;;\n");

