fn generate_cmd_parse(cmd: &Command, func_prefix: &str) -> String {
    let mut s = String::new();

    let fn_name = if func_prefix == cmd.name {
        "_argc_parse".to_string()
    } else {
        format!("_argc_parse_{}", cmd.name)
    };

    s.push_str(&format!("{}() {{\n", fn_name));
    s.push_str("    local _argc_key _argc_action\n");

    if !cmd.subcommands.is_empty() {
        let mut subs = Vec::new();
        for sub in &cmd.subcommands {
            subs.push(sub.name.clone());
            for a in &sub.aliases {
                subs.push(a.clone());
            }
        }
        s.push_str(&format!("    local _argc_subcmds=\"{}\"\n", subs.join(", ")));
    } else {
        s.push_str("    local _argc_subcmds=\"\"\n");
    }

    s.push_str("    while [[ $_argc_index -lt $_argc_len ]]; do\n");
    s.push_str("        _argc_item=\"${argc__args[_argc_index]}\"\n");
    s.push_str("        _argc_key=\"${_argc_item%%=*}\"\n");
    s.push_str("        case \"$_argc_key\" in\n");

    s.push_str("        --help | -help | -h)\n");
    if func_prefix == cmd.name {
        s.push_str("            _argc_usage\n");
    } else {
        s.push_str(&format!("            _argc_usage_{}\n", cmd.name));
    }
    s.push_str("            ;;\n");

    s.push_str("        --version | -version | -V)\n");
    s.push_str("            _argc_version\n");
    s.push_str("            ;;\n");

    for fo in &cmd.flag_options {
        if fo.id == "help" || fo.id == "version" {
            continue;
        }
        let mut pat_parts = Vec::new();
        if let Some(l) = &fo.long_name {
            pat_parts.push(l.clone());
        }
        if let Some(s_name) = &fo.short_name {
            pat_parts.push(s_name.clone());
        }
        if pat_parts.is_empty() {
            continue;
        }
        let pat_str = pat_parts.join(" | ");
        s.push_str(&format!("        {})\n", pat_str));
        if fo.flag {
            s.push_str(&format!("            argc_{}=1\n", fo.id));
            s.push_str("            _argc_index=$((_argc_index + 1))\n");
        } else {
            let l_name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or(&fo.id);
            s.push_str(&format!("            _argc_take_args \"{}\" {} {} \"-\" \"\"\n", l_name, fo.num_args.0, fo.num_args.1));
            s.push_str("            _argc_index=$((_argc_index + _argc_take_args_len + 1))\n");
            s.push_str(&format!("            argc_{}=\"${{_argc_take_args_values[0]:-}}\"\n", fo.id));
        }
        s.push_str("            ;;\n");
    }

    s.push_str("        --)\n");
    s.push_str("            _argc_dash=\"${#argc__positionals[@]}\"\n");
    s.push_str("            argc__positionals+=(\"${argc__args[@]:$((_argc_index + 1))}\")\n");
    s.push_str("            _argc_index=$_argc_len\n");
    s.push_str("            break\n");
    s.push_str("            ;;\n");

    for sub in &cmd.subcommands {
        let mut pattern = sub.name.clone();
        for a in &sub.aliases {
            pattern.push_str(&format!(" | {}", a));
        }
        s.push_str(&format!("        {})\n", pattern));
        s.push_str("            _argc_index=$((_argc_index + 1))\n");
        s.push_str(&format!("            _argc_action=_argc_parse_{}\n", sub.name));
        s.push_str("            break\n");
        s.push_str("            ;;\n");
    }

    s.push_str("        *)\n");
    if !cmd.subcommands.is_empty() {
        s.push_str(&format!(
            "            _argc_die \"error: `{}` requires a subcommand but one was not provided\"$'\\n'\"  [subcommands: $_argc_subcmds]\"\n",
            cmd.name
        ));
    } else {
        s.push_str("            argc__positionals+=(\"$_argc_item\")\n");
        s.push_str("            _argc_index=$((_argc_index + 1))\n");
    }
    s.push_str("            ;;\n");

    s.push_str("        esac\n");
    s.push_str("    done\n");

    s.push_str("    if [[ -n \"${_argc_action:-}\" ]]; then\n");
    s.push_str("        $_argc_action\n");
    s.push_str("    else\n");
    if let Some(command_fn) = &cmd.command_fn {
        s.push_str(&format!("        argc__fn={}\n", command_fn));
    } else if !cmd.subcommands.is_empty() {
        s.push_str("        _argc_usage\n");
    }

    if !cmd.positionals.is_empty() {
        let is_multi_vec: Vec<String> = cmd.positionals.iter().map(|p| if p.multiple { "1" } else { "0" }).collect();
        s.push_str(&format!("        _argc_match_positionals {}\n", is_multi_vec.join(" ")));
        for (p_i, pos) in cmd.positionals.iter().enumerate() {
            s.push_str("        local values_index values_size\n");
            s.push_str(&format!("        IFS=: read -r values_index values_size <<<\"${{_argc_match_positionals_values[{}]:-}}\"\n", p_i));
            s.push_str("        if [[ -n \"$values_index\" ]]; then\n");
            s.push_str(&format!("            argc_{}=\"${{argc__positionals[values_index]}}\"\n", pos.id));
            if pos.required {
                s.push_str("        else\n");
                s.push_str(&format!("            _argc_die \"error: the following required arguments were not provided: <{}>\"\n", pos.notation));
            }
            s.push_str("        fi\n");
        }
    }

    s.push_str("    fi\n");

    s.push_str("}\n\n");

    s
}

fn format_build_usage(cmd: &Command) -> String {
    let mut lines = Vec::new();

    if !cmd.describe.is_empty() {
        lines.push(cmd.describe.clone());
        lines.push(String::new());
    }

    let mut usage = format!("USAGE: {}", cmd.name);
    if !cmd.subcommands.is_empty() {
        usage.push_str(" <COMMAND>");
    } else {
        if !cmd.flag_options.is_empty() {
            usage.push_str(" [OPTIONS]");
        }
        for pos in &cmd.positionals {
            if pos.required {
                usage.push_str(&format!(" <{}>", pos.notation));
            } else {
                usage.push_str(&format!(" [{}]", pos.notation));
            }
        }
    }
    lines.push(usage);

    if !cmd.subcommands.is_empty() {
        lines.push(String::new());
        lines.push("COMMANDS:".to_string());
        for sub in &cmd.subcommands {
            let mut name_str = sub.name.clone();
            if !sub.aliases.is_empty() {
                name_str.push_str(&format!(" [aliases: {}]", sub.aliases.join(", ")));
            }
            if sub.describe.is_empty() {
                lines.push(format!("  {}", name_str));
            } else {
                lines.push(format!("  {:10}  {}", name_str, sub.describe));
            }
        }
    }

    lines.join("\n")
}
