                s.push_str(&format!("            _argc_die \"error: the required environments `<{}>` were not provided\"\n", pos.notation));
            }
            s.push_str("        fi\n");
        }
    }

    s.push_str("    fi\n");

    s.push_str("}\n\n");

    s
}

